//! Material 3 theming: the palette (from end4-pC's colors, a matugen
//! `theme.json`, or a seed color), the egui style built from it, and
//! [`ThemeManager`], which keeps an app's look in sync with the desktop.

pub mod palette;
pub mod style;

pub use palette::M3Palette;

use serde::{Deserialize, Serialize};
use std::path::{Path, PathBuf};
use std::time::Duration;

/// Colors generated by illogical-impulse / end4-pC on every wallpaper or
/// color-scheme change.
pub fn end4_colors_path() -> Option<PathBuf> {
    dirs::state_dir().map(|d| d.join("quickshell/user/generated/colors.json"))
}

/// The Material 3 File Manager's matugen output, for non-end4 setups.
pub fn file_manager_theme_path() -> Option<PathBuf> {
    dirs::config_dir().map(|d| d.join("material_3_file_manager/theme.json"))
}

/// First palette file that exists, in priority order.
pub fn auto_theme_path() -> Option<PathBuf> {
    [end4_colors_path(), file_manager_theme_path()]
        .into_iter()
        .flatten()
        .find(|p| p.is_file())
}

#[derive(Clone, Copy, Debug, Default, Deserialize, Serialize, PartialEq, Eq)]
#[serde(rename_all = "lowercase")]
pub enum ColorScheme {
    #[default]
    System,
    Light,
    Dark,
}

/// Where the palette comes from.
#[derive(Clone, Copy, Debug, Default, Deserialize, Serialize, PartialEq, Eq)]
#[serde(rename_all = "lowercase")]
pub enum ThemeSource {
    /// The desktop's colors (end4-pC, else the file manager's theme.json),
    /// else the seed color.
    #[default]
    Auto,
    /// Always the seed color.
    Seed,
}

/// The appearance settings every Material 3 app shares. Embed it in an
/// app's config (`#[serde(default)] appearance: ThemeSettings`).
#[derive(Clone, Debug, Deserialize, Serialize, PartialEq)]
#[serde(default)]
pub struct ThemeSettings {
    pub source: ThemeSource,
    pub scheme: ColorScheme,
    pub seed_color: String,
    pub filled_icons: bool,
    pub ui_scale: f32,
}

impl Default for ThemeSettings {
    fn default() -> Self {
        Self {
            source: ThemeSource::Auto,
            scheme: ColorScheme::System,
            seed_color: palette::DEFAULT_SEED.into(),
            filled_icons: true,
            ui_scale: 1.0,
        }
    }
}

/// Applies [`ThemeSettings`] to an egui context and keeps it current: the
/// desktop's palette file is watched, and the system light/dark preference
/// is followed. Call [`ThemeManager::poll`] once per frame.
pub struct ThemeManager {
    ctx: egui::Context,
    palette: M3Palette,
    system_dark: Option<bool>,
    _watcher: Option<notify::RecommendedWatcher>,
    events: flume::Receiver<PathBuf>,
    error: Option<String>,
}

impl ThemeManager {
    /// Installs fonts and icons, applies `settings`, and starts watching.
    pub fn new(ctx: &egui::Context, settings: &ThemeSettings) -> Self {
        style::install_fonts(ctx);
        let (tx, events) = flume::unbounded();
        let watcher = {
            use notify::Watcher;
            let repaint = ctx.clone();
            notify::recommended_watcher(move |res: notify::Result<notify::Event>| {
                if let Ok(ev) = res {
                    if ev.kind.is_create() || ev.kind.is_modify() {
                        for p in ev.paths {
                            let _ = tx.send(p);
                        }
                        repaint.request_repaint_after(Duration::from_millis(150));
                    }
                }
            })
            .ok()
            .map(|mut w| {
                for file in [end4_colors_path(), file_manager_theme_path()].into_iter().flatten() {
                    if let Some(dir) = file.parent().filter(|d| d.is_dir()) {
                        let _ = w.watch(dir, notify::RecursiveMode::NonRecursive);
                    }
                }
                w
            })
        };
        let mut manager = Self {
            ctx: ctx.clone(),
            palette: M3Palette::from_seed(palette::DEFAULT_SEED, true),
            system_dark: ctx.system_theme().map(|t| t == egui::Theme::Dark),
            _watcher: watcher,
            events,
            error: None,
        };
        manager.apply(settings);
        manager
    }

    pub fn palette(&self) -> &M3Palette {
        &self.palette
    }

    /// The palette file in use, if any.
    pub fn theme_file(&self, settings: &ThemeSettings) -> Option<PathBuf> {
        match settings.source {
            ThemeSource::Auto => auto_theme_path(),
            ThemeSource::Seed => None,
        }
    }

    /// A message when the palette file couldn't be read (taken once).
    pub fn take_error(&mut self) -> Option<String> {
        self.error.take()
    }

    fn wants_dark(&self, settings: &ThemeSettings) -> bool {
        match settings.scheme {
            ColorScheme::Light => false,
            ColorScheme::Dark => true,
            ColorScheme::System => self.system_dark.unwrap_or(true),
        }
    }

    /// Re-apply after the settings changed.
    pub fn apply(&mut self, settings: &ThemeSettings) {
        let dark = self.wants_dark(settings);
        let palette = match self.theme_file(settings) {
            Some(path) => match M3Palette::from_theme_json(&path) {
                Ok(p) => p,
                Err(e) => {
                    self.error = Some(format!("Couldn't read {}: {e}", path.display()));
                    M3Palette::from_seed(&settings.seed_color, dark)
                }
            },
            None => M3Palette::from_seed(&settings.seed_color, dark),
        };
        style::apply(&self.ctx, &palette);
        crate::widgets::set_palette(&self.ctx, palette.clone());
        crate::widgets::set_filled_icons(settings.filled_icons);
        let scale = settings.ui_scale.clamp(0.6, 2.5);
        if (self.ctx.zoom_factor() - scale).abs() > f32::EPSILON {
            self.ctx.set_zoom_factor(scale);
        }
        self.palette = palette;
    }

    /// Pick up palette-file changes and system light/dark switches. Returns
    /// true when the theme was re-applied.
    pub fn poll(&mut self, settings: &ThemeSettings) -> bool {
        let changed: Vec<PathBuf> = self.events.try_iter().collect();
        let mut reapply = false;
        if let Some(theme) = self.theme_file(settings) {
            reapply |= changed.iter().any(|p| same_file(p, &theme));
        }
        let system_dark = self.ctx.system_theme().map(|t| t == egui::Theme::Dark);
        if system_dark != self.system_dark {
            self.system_dark = system_dark;
            reapply |= settings.scheme == ColorScheme::System && self.theme_file(settings).is_none();
        }
        if reapply {
            self.apply(settings);
        }
        reapply
    }
}

fn same_file(a: &Path, b: &Path) -> bool {
    a == b || a.file_name() == b.file_name() && a.parent() == b.parent()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn settings_defaults_and_round_trip() {
        let s: ThemeSettings = serde_json::from_str(r##"{"seed_color":"#FF0000"}"##).unwrap();
        assert_eq!(s.seed_color, "#FF0000");
        assert_eq!(s.source, ThemeSource::Auto);
        assert!(s.filled_icons);
        let back: ThemeSettings = serde_json::from_str(&serde_json::to_string(&s).unwrap()).unwrap();
        assert_eq!(back, s);
    }
}
